def dispatch(operation, token, reader, writer):
    if operation == 'read':
        return reader()
    if not token:
        raise PermissionError('token required')
    return writer()

def consume(resource):
    try:
        return resource.read()
    finally:
        resource.close()

def store(event, registry):
    sink = registry.lookup('durable')
    return sink.append(event)

def submit(value, publish):
    if value < 0:
        return False
    publish(value)
    return True
